const color = $json.color || "blue";
const design = $json.design || "minimal";
const termTopic = $json.termTopic || "Reinforcement";

// 这个 pageCount 只是给 AI 用，不给 HTML
const pageCount = 6;

// 用于生成唯一任务 ID
const jobId = new Date().toISOString().replace(/[-:.TZ]/g, "").slice(0, 14);

return [{
  json: {
    color,
    design,
    termTopic,
    pageCount,
    jobId
  }
}];

// ===== 强制 BCBA Markdown 格式标准化 =====

// 1️⃣ 读取 AI 输出
let text = $json.output;

if (!text || typeof text !== 'string') {
  throw new Error('AI output is empty or invalid');
}

// 2️⃣ 统一换行
text = text.replace(/\r\n/g, '\n').trim();

// 3️⃣ 移除所有多余的 ---（先全清）
text = text.replace(/\n?---\n?/g, '\n');

// 4️⃣ 强制在 Subtitle 后插入唯一的 ---
const subtitleMatch = text.match(/Subtitle:.*\n/);
if (!subtitleMatch) {
  throw new Error('Missing Subtitle line');
}

const insertIndex = subtitleMatch.index + subtitleMatch[0].length;
text =
  text.slice(0, insertIndex) +
  '\n---\n' +
  text.slice(insertIndex).trimStart();

// 5️⃣ 禁止 Page 2+ 前出现 ---
const invalidPattern = /\n---\n\s*\[Page (?!1)/;
if (invalidPattern.test(text)) {
  throw new Error("Invalid '---' placement before Page 2+");
}

// 6️⃣ 校验 bullet 长度（<=12词）
const bullets = text.split('\n').filter(l => l.trim().startsWith('- '));
for (const line of bullets) {
  const wordCount = line.replace('- ', '').trim().split(/\s+/).length;
  if (wordCount > 12) {
    throw new Error(`Bullet exceeds 12 words: ${line}`);
  }
}

// 7️⃣ 最终结构校验
if (!text.includes('\n---\n[Page 1]')) {
  throw new Error("Final structure invalid: '---' must precede [Page 1]");
}

// 8️⃣ 输出标准字段
return [
  {
    json: {
      markdown: text
    }
  }
];

// 1. 拿到 voices 列表
const voices = $input.first().json.voices || [];

// 2. 找到你要的 voice
const targetName = "George - Warm, Captivating Storyteller";
const targetVoice = voices.find(v => v.name === targetName);

if (!targetVoice) {
  throw new Error("Target voice not found");
}

// 3. 把 voice 信息附加到「原始输入的每一条 item」
return $input.all().map(item => ({
  json: {
    ...item.json,
    voice_id: targetVoice.voice_id,
    voice_name: targetVoice.name,
    voice_category: targetVoice.category
  }
}));

// 你在 Edit Fields 里填的名字（只取第一条输入即可）
const target = (($input.first().json.targetVoiceName) || "").trim();

// 从 “TTS” 节点（GET /v1/voices）的输出取数据
// 注意：这里的 "TTS" 必须和你左侧节点名字完全一致
const ttsItems = $items("TTS");
if (!ttsItems || !ttsItems.length) {
  throw new Error('No output from node "TTS". Please execute the TTS (GET /v1/voices) node first.');
}

// TTS 节点通常只输出 1 item，其中 json.voices 是数组
const voices = ttsItems[0].json.voices || [];
if (!voices.length) {
  throw new Error('TTS node returned no voices[]. Check your API key / headers and rerun TTS node.');
}

const found = voices.find(v => ((v.name || "").trim() === target));
if (!found) {
  throw new Error(`Voice not found: "${target}". Copy the exact name from List Voices.`);
}

// 只输出 1 条 item，避免后面跑 20 次
return [{
  json: {
    targetVoiceName: target,
    voice_name: found.name,
    voice_id: found.voice_id,
    category: found.category,
  }
}];

// 1️⃣ 只取一个 voice（Find Voice ID 一定是 1 item）
const voice = $items("Find Voice ID")[0].json;

// 2️⃣ 取每一页真正的文本（来自 Code in JavaScript4）
const pages = $items("Code in JavaScript4");

return pages.map(item => ({
  json: {
    // ✅ TTS 真正朗读的文本（唯一来源）
    text: item.json.text,

    // ✅ ElevenLabs 必须的 voice
    voice_id: voice.voice_id,
    voice_name: voice.voice_name,

    // （可选）保留这些，方便你后面 ffmpeg 用
    pageIndex: item.json.pageIndex,
    imagePath: item.json.imagePath,
    audioPath: item.json.audioPath
  }
}));

const results = items.map(item => {
  const { page, imagePath, text } = item.json;

  // ✅ 正确判断方式（允许 page = 0）
  if (page === undefined || !imagePath || !text) {
    throw new Error(`❌ Missing data on page ${page}`);
  }

  return {
    json: {
      page,
      imagePath,
      text,
      audioFile: `page-${page}.mp3`
    }
  };
});

return results;

const results = items.map((item, index) => {

  // 如果没有 page，就用 index
  const page = item.json.page ?? index;

  // 如果 imagePath 不存在，从 Merge 或上一节点读取
  const imagePath =
    item.json.imagePath ??
    item.json.image_path ??
    null;

  if (!imagePath) {
    throw new Error(`Missing imagePath at item ${index}`);
  }

  return {
    json: {
      pageIndex: page,
      imagePath: imagePath,
      audioPath: `/data/page-${page}.mp3`
    },
    binary: {
      audio: item.binary?.audio
    }
  };

});

return results;

const fullText = $json.output;

const results = [];

/* Cover */
const coverMatch = fullText.match(/\[Cover\][\s\S]*?(?=\[Page|$)/i);

if (coverMatch) {
  const clean = coverMatch[0]
    .replace(/\[Cover\]/i, '')
    .trim();

  results.push({
    json: {
      page: 0,
      text: clean
    }
  });
}

/* Pages */
const pageRegex = /\[Page\s*(\d+)\][\s\S]*?(?=\[Page\s*\d+\]|$)/g;

let match;

while ((match = pageRegex.exec(fullText)) !== null) {
  const pageNumber = Number(match[1]);

  const cleanText = match[0]
    .replace(/\[Page\s*\d+\]/, '')
    .trim();

  results.push({
    json: {
      page: pageNumber,
      text: cleanText
    }
  });
}

results.sort((a, b) => a.json.page - b.json.page);

return results;

const items = $input.all();

for (const item of items) {
  if (item.binary?.data) {
    // 关键：让 YouTube 节点不要拼出 application/mp4
    item.binary.data.fileExtension = 'octet-stream';
    item.binary.data.mimeType = 'application/octet-stream';

    // 可选：文件名你想保留 mp4 也行
    item.binary.data.fileName = item.binary.data.fileName || 'video.mp4';
  }
}

return items;

