const httpItem = items[0].json;
const runDir = httpItem.runDir;
const files = httpItem.files || [];

const results = [];

files.forEach(file => {

  // ✅ 1️⃣ 处理 cover
  if (file === 'cover.png') {
    results.push({
      json: {
        page: 0,
        imagePath: `${runDir}/${file}`
      }
    });
    return;
  }

  // ✅ 2️⃣ 处理 page-x
  const match = file.match(/page-(\d+)\.png/);
  if (!match) return;

  const page = Number(match[1]);

  results.push({
    json: {
      page,
      imagePath: `${runDir}/${file}`
    }
  });

});

// ✅ 排序（防止 cover 跑到最后）
results.sort((a, b) => a.json.page - b.json.page);

return results;

// ⚠️ 这里的 runId 以后可以动态，现在先用已有的
const runId = $('HTTP Request').first().json.runDir;

return [
  {
    json: {
      runId,

      // renderer 已有的图片目录（不改 renderer）
      imageDir: `${runId}`,

      // mp3 已经写入的目录（你现在就在用）
      audioDir: `/data`,

      // ffmpeg 最终统一工作目录
      runDir: `/data/${runId}`
    }
  }
];

const data = items[0].json;

const color = $input.first().json.data.items[0].fields.color;
const design = $input.first().json.data.items[0].fields.design;
const termTopic =  $input.first().json.data.items[0].fields.termTopic[0].text;

return [
  {
    json: {
      color,
      design,
      termTopic
    }
  }
];
